static int max_int(int a, int b) {
    return a > b ? a : b;
}

bool increment(int *value) {
    if (value == NULL) return false;
    ++*value;
    return true;
}

static unsigned long call_count;

void record_call(void) {
    ++call_count;
}

unsigned long long factorial(unsigned n) {
    if (n <= 1u) return 1u;
    return n * factorial(n - 1u);
}
